const GEKO_LOGO_B64 = "data:image/png;base64,";
const ISO14001_LOGO_B64 = "data:image/png;base64,";
const ISO9001_LOGO_B64 = "data:image/png;base64,";

// Layout-Koordinaten (mm), exakt aus dem GEKO-Template (Vorlage_Leistungsnachweis_Graffiti.pdf)
// gemessen. Einheit: mm, Ursprung oben links (passend zu jsPDF unit:"mm").
const LAYOUT = {
  left: 25.08,
  right: 184.8,
  title: { x: 25.08, y: 31.3, size: 14 },
  logoTop: { x: 158, y: 12.9, w: 18, h: 29.1 },

  auftraggeberLabel: { x: 26.15, y: 57.39 },
  auftraggeberContentX: 37.57,
  auftraggeberFirstLineGap: 10.41,  // Lücke Label -> 1. Zeile (eine Leerzeile, wie im Original)

  objektLabel: { x: 26.15 },
  objektLabelGap: 10.25,             // Lücke letzte Auftraggeber-Zeile -> "Objekt"-Label
  objektContentX: 37.57,
  objektFirstLineGap: 5.16,          // keine Leerzeile, direkt weiter

  lineGap: 5.16,                     // normaler Zeilenabstand im Adressblock

  kontaktX: 131.68,
  kontaktGapFromObjektEnd: 5.16,      // "Kontakt:" beginnt eine Zeile unter dem Objekt-Block

  kategorieGap: 16.26,                // Abstand von Ende Objekt-/Kontaktblock (je tiefer) bis Kategorie

  line1GapAfterKategorie: 10.52,
  rowGapAfterLine1: 7.68,
  line2GapAfterRow: 2.48,
  bulletGapAfterLine2: 10.04,
  bulletLineGap: 5.16,
  bulletDashX: 31.43,
  bulletTextX: 37.78,
  kdnrX: 123.83,

  disclaimerY: 226.97,
  disclaimerLineGap: 5.17,

  sigLineY: 243.82,
  sigLabelGap: 5.17,
  unterschriftLabelX: 87.52,

  logoBottom: { y: 258.4, h: 14.4, x1: 102.45, w1: 38.3, x2: 145.8, w2: 38.3 },
};

function generatePdf(s) {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const L = LAYOUT;

  doc.setFont("helvetica", "normal");

  // Titel
  doc.setFontSize(L.title.size);
  doc.setFont("helvetica", "bold");
  doc.text("Abnahmebescheinigung", L.title.x, L.title.y);

  // Logo oben rechts
  doc.addImage(GEKO_LOGO_B64, "PNG", L.logoTop.x, L.logoTop.y, L.logoTop.w, L.logoTop.h);

  // Auftraggeber
  let y = L.auftraggeberLabel.y;
  doc.setFontSize(11);
  doc.setFont("helvetica", "bold");
  doc.text("Auftraggeber", L.auftraggeberLabel.x, y);

  y += L.auftraggeberFirstLineGap;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10.5);
  const kundeLines = (s.kunde || "").split("\n").filter((l) => l.trim());
  kundeLines.forEach((line, i) => {
    doc.text(line, L.auftraggeberContentX, y + i * L.lineGap);
  });
  y += Math.max(kundeLines.length, 1) * L.lineGap - L.lineGap;

  // Objekt
  y += L.objektLabelGap;
  doc.setFontSize(11);
  doc.setFont("helvetica", "bold");
  doc.text("Objekt", L.objektLabel.x, y);

  let objektStartY = y + L.objektFirstLineGap;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10.5);
  const adresseLines = (s.adresse || "").split("\n").filter((l) => l.trim());
  adresseLines.forEach((line, i) => {
    doc.text(line, L.objektContentX, objektStartY + i * L.lineGap);
  });
  const objektEndY = objektStartY + Math.max(adresseLines.length, 1) * L.lineGap - L.lineGap;

  // Kontakt (rechte Spalte), beginnt eine Zeile unter dem Objekt-Block
  let ky = objektEndY + L.kontaktGapFromObjektEnd;
  doc.setFontSize(11);
  doc.setFont("helvetica", "bold");
  doc.text("Kontakt:", L.kontaktX, ky);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10.5);
  if (s.ansprechpartner) {
    ky += L.lineGap;
    doc.text(`AP: ${s.ansprechpartner}`, L.kontaktX, ky);
  }
  if (s.telefon) {
    ky += L.lineGap;
    doc.text(`Tel: ${s.telefon}`, L.kontaktX, ky);
  }

  // Kategorie
  y = Math.max(objektEndY, ky) + L.kategorieGap;
  doc.setFontSize(11);
  doc.setFont("helvetica", "bold");
  doc.text(s.kategorie || "", L.left, y);

  // Linie 1
  let lineY = y + L.line1GapAfterKategorie;
  doc.setDrawColor(140, 140, 140);
  doc.setLineWidth(0.2);
  doc.line(L.left, lineY, L.right, lineY);

  // Auszuführende Arbeiten / Kd.-Nr. Zeile
  const rowY = lineY + L.rowGapAfterLine1;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10.5);
  doc.text(`Auszuführende Arbeiten Monat:  ${s.monat || ""}`, L.left, rowY);
  doc.text(`Kd.-Nr.:  ${s.kdnr || ""}`, L.kdnrX, rowY);

  // Linie 2
  const line2Y = rowY + L.line2GapAfterRow;
  doc.line(L.left, line2Y, L.right, line2Y);

  // Leistungen (Bulletpoints)
  let by = line2Y + L.bulletGapAfterLine2;
  const leistungen = (s.leistungen || "").split("\n").filter((l) => l.trim());
  leistungen.forEach((line) => {
    doc.setFont("helvetica", "bold");
    doc.text("-", L.bulletDashX, by);
    doc.setFont("helvetica", "normal");
    doc.text(line.trim(), L.bulletTextX, by);
    by += L.bulletLineGap;
  });

  // Hinweistext
  doc.setFontSize(10.5);
  doc.setFont("helvetica", "normal");
  doc.text("Die ordnungsgemäße Durchführung der Arbeiten wird bestätigt!", L.left, L.disclaimerY);
  doc.text("Spätere Reklamation können nicht anerkannt werden.", L.left, L.disclaimerY + L.disclaimerLineGap);

  // Unterschrift-Bereich (bewusst weiter rechts, im freien Bereich, fern vom Hinweistext)
  const sigX = 135;
  const sigW = 45;
  const sigH = 18;
  if (s.unterschrift) {
    try {
      doc.addImage(s.unterschrift, "PNG", sigX, L.sigLineY - sigH - 2, sigW, sigH);
    } catch (e) {}
  }
  if (s.unterschrift_name) {
    doc.setFontSize(8.5);
    doc.setFont("helvetica", "italic");
    doc.text(s.unterschrift_name, sigX, L.sigLineY - 1.5);
  }
  if (s.datum) {
    doc.setFontSize(10.5);
    doc.setFont("helvetica", "normal");
    doc.text(formatDate(s.datum), L.left, L.sigLineY - 1.5);
  }

  doc.setLineDashPattern([1, 1], 0);
  doc.line(L.left, L.sigLineY, L.right, L.sigLineY);
  doc.setLineDashPattern([], 0);

  doc.setFontSize(9.5);
  doc.text("Datum", L.left, L.sigLineY + L.sigLabelGap);
  doc.text("Unterschrift des Auftraggebers", L.unterschriftLabelX, L.sigLineY + L.sigLabelGap);

  // Footer-Logos
  doc.addImage(ISO14001_LOGO_B64, "PNG", L.logoBottom.x1, L.logoBottom.y, L.logoBottom.w1, L.logoBottom.h);
  doc.addImage(ISO9001_LOGO_B64, "PNG", L.logoBottom.x2, L.logoBottom.y, L.logoBottom.w2, L.logoBottom.h);

  return doc;
}

function formatDate(iso) {
  if (!iso) return "";
  const [y, m, d] = iso.split("-");
  return `${d}.${m}.${y}`;
}
